function canCompleteCircuit(gas: number[], cost: number[]): number {
  let total = 0; // общий баланс топлива за весь круг
  let tank = 0; // топливо в баке с момента текущего кандидата start
  let start = 0; // кандидат на стартовую заправку

  for (let i = 0; i < gas.length; i++) {
    const diff = gas[i] - cost[i];
    total += diff;
    tank += diff;

    // Не доехали от start до i + 1. Ни одна заправка из [start, i]
    // не подходит как старт — следующий кандидат i + 1
    if (tank < 0) {
      start = i + 1;
      tank = 0;
    }
  }

  // Если топлива суммарно меньше, чем расход, круг невозможен.
  // Иначе последний кандидат гарантированно подходит
  return total >= 0 ? start : -1;
}

// Время: O(n) — один проход
// Память: O(1)
